  flex: 0 0 auto;
}

.tool {
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 7px;
  padding: 5px 12px;
  font-size: 13px;
  cursor: pointer;
}

.spacer { flex: 1; }
.tool-note { font-size: 12px; color: var(--muted); }

.surface {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 10px 18px;
  outline: none;
  line-height: 1.55;
  font-size: 15px;
}

.log-block {
  margin: 0 0 10px;
  white-space: pre-wrap;
}

.status-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  background: var(--bar);
  border-top: 1px solid var(--line);
  font-size: 12px;
  color: var(--muted);
  flex: 0 0 auto;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}

